--
-- Table structure for table `ip_log`
--

DROP TABLE IF EXISTS `ip_log`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `ip_log` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `sid` varchar(100) DEFAULT NULL,
  `ip` varchar(45) DEFAULT NULL,
  `ip_time` datetime DEFAULT NULL,
  `area` varchar(45) DEFAULT NULL,
  `uri` varchar(45) DEFAULT NULL,
  `response_time` bigint(20) DEFAULT NULL,
  `visit_num` int(11) DEFAULT NULL,
  `referer` varchar(1000) DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=53101 DEFAULT CHARSET=utf8;
/*!40101 SET character_set_client = @saved_cs_client */;

